<?php
require dirname(__DIR__) . '/config.php'; require_admin();
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$id=(int)$_POST['id'];$a=$_POST['action']??'';if($a==='delete')db()->prepare('DELETE FROM messages WHERE id=?')->execute([$id]);if($a==='read')db()->prepare('UPDATE messages SET is_read=1 WHERE id=?')->execute([$id]);flash('Message updated.');redirect('admin/messages.php');}
$selected=null;if(isset($_GET['id'])){$q=db()->prepare('SELECT * FROM messages WHERE id=?');$q->execute([(int)$_GET['id']]);$selected=$q->fetch();if($selected)db()->prepare('UPDATE messages SET is_read=1 WHERE id=?')->execute([$selected['id']]);}
$rows=db()->query('SELECT * FROM messages ORDER BY created_at DESC')->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Messages</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="../assets/style.css" rel="stylesheet"></head><body class="dashboard"><div class="admin-shell"><?php include 'nav.php';?><main class="admin-main"><div class="admin-top"><div><span class="eyebrow">INBOX</span><h1>Contact messages</h1></div></div><?php show_flash();?><?php if($selected):?><div class="admin-panel mb-4"><a href="messages.php">← Back to inbox</a><h2 class="mt-3"><?=e($selected['subject']?:'No subject')?></h2><p class="muted">From <?=e($selected['name'])?> · <a href="mailto:<?=e($selected['email'])?>"><?=e($selected['email'])?></a> · <?=e($selected['created_at'])?></p><p class="message-content"><?=nl2br(e($selected['message']))?></p><form method="post" onsubmit="return confirm('Delete this message?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$selected['id']?>"><input type="hidden" name="action" value="delete"><button class="btn btn-outline-danger">Delete message</button></form></div><?php endif;?>
<div class="admin-panel"><div class="table-responsive"><table class="table table-dark table-hover"><thead><tr><th>Status</th><th>Name / email</th><th>Subject</th><th>Received</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=$r['is_read']?'Read':'<span class="text-info">New</span>'?></td><td><?=e($r['name'])?><br><small class="muted"><?=e($r['email'])?></small></td><td><?=e($r['subject'])?></td><td><?=e($r['created_at'])?></td><td><a href="?id=<?=$r['id']?>">Read</a></td></tr><?php endforeach;?></tbody></table></div><?php if(!$rows):?><p class="muted">Your inbox is empty.</p><?php endif;?></div></main></div></body></html>
